{
  "name": "Prescription Template",
  "description": "Extract medication and prescription fields from a document image",
  "fields": [
    {
      "name": "Patient Name",
      "description": "Full name of the patient on the prescription",
      "data_type": "string",
      "required": true
    },
    {
      "name": "Prescription Lines",
      "description": "List each prescribed medication line when the document contains multiple medications",
      "data_type": "array<object>",
      "required": false,
      "object_schema": {
        "mode": "table",
        "columns": [
          {
            "heading": "Medication Name",
            "data_type": "string",
            "description": "Medication listed on this line"
          },
          {
            "heading": "Strength",
            "data_type": "string",
            "description": "Strength for this medication line"
          },
          {
            "heading": "Dose Instructions",
            "data_type": "string",
            "description": "Dose and frequency instructions for this line"
          }
        ]
      }
    }
  ]
}

